      await pool.query(
        `UPDATE operations.customer_erasure_requests
         SET status='failed',last_error='erasure_cleanup_failed',lease_expires_at=NULL,updated_at=now()
         WHERE id=$1 AND locked_by=$2`,
        [request.id, this.workerId],
      );
    }
    return true;
